        function parseVariants(vStr) {
            if(!vStr) return [];
            let arr = [];
            let parts = vStr.split(',');
            parts.forEach(p => {
                let kv = p.split('-');
                if(kv.length >= 2) {
                    let vObj = { name: kv[0].trim(), price: Number(kv[1].trim()) };
                    if (kv.length >= 3 && kv[2].trim() !== '') {
                        vObj.stock = Number(kv[2].trim());
                    }
                    arr.push(vObj);
                }
            });
            return arr;
        }
